@use "sass:map";
@use "sass:meta";
@use "sass:string";

@use "@fontsource-utils/scss" as fontsource;
@use "@fontsource/inter/scss" as inter;

// Tabler Icons >= 3.36.1 ships filled icons in a dedicated font, with a custom prefix to not collide with outline `.ti` classes.
@use "@tabler/icons-webfont/dist/tabler-icons-filled" as ti-filled with (
    $ti-font-path: "@tabler/icons-webfont/dist/fonts",
    $ti-prefix: "ti-filled"
);

$enable-negative-margins: true;
$link-hover-decoration: none;

@import "@tabler/core/scss/core";

@include fontsource.faces(
    $metadata: inter.$metadata,
    $subsets: all,
    $weights: all,
    $styles: normal
);

:root {
    --tblr-font-sans-serif: inter, -apple-system, blinkmacsystemfont, san francisco, segoe ui, roboto, helvetica neue, sans-serif;
}

$ti-font-path: "@tabler/icons-webfont/dist/fonts";

@import "@tabler/icons-webfont/dist/tabler-icons";

// Restore legacy `ti-{name}-filled` classes; declared after `.ti` to override its font family.
%ti-filled-font {
    font-family: ti-filled.$ti-font-family !important;
}

@each $variable in map.keys(meta.module-variables("ti-filled")) {
    @if string.index($variable, "ti-icon-") == 1 {
        $name: string.slice($variable, 9);

        .ti-#{$name}-filled {
            @extend %ti-filled-font;
            @extend .ti-filled-#{$name};
        }
    }
}
